"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Home, FileText, UserCircle, Calendar, Users, Settings } from "lucide-react";
import { useUser } from "@stackframe/stack";
import Topbar from "@/components/Topbar";
import DashboardContainer from "@/components/DashboardContainer";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";

interface Interview {
  id: number;
  role: string;
  interview_type: string;
  experience_level: string;
  num_questions: number;
  questions: string[];
  responses: string[];
  feedback: object;
  created_at: string;
}

export default function DashboardPage() {
  const user = useUser();
  const router = useRouter();
  const [isScrolled, setIsScrolled] = useState(false);
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [chatbotOpen, setChatbotOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Interview generation form state
  const [role, setRole] = useState("");
  const [interviewType, setInterviewType] = useState("");
  const [experienceLevel, setExperienceLevel] = useState("");
  const [numQuestions, setNumQuestions] = useState(5);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 10);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Redirect if not signed in
  useEffect(() => {
    if (!user) {
      router.push("/auth/signin");
    }
  }, [user, router]);

  // Fetch interviews on component mount
  useEffect(() => {
    fetchInterviews();
  }, []);

  const fetchInterviews = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/interviews/');
      if (response.ok) {
        const data = await response.json();
        setInterviews(data);
      }
    } catch (error) {
      console.error('Error fetching interviews:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateInterview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!role || !interviewType || !experienceLevel) {
      alert('Please fill in all fields');
      return;
    }

    setGenerating(true);
    try {
      const response = await fetch('/api/interviews/create/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          role,
          type: interviewType,
          level: experienceLevel,
          num_questions: numQuestions,
        }),
      });

      if (response.ok) {
        const newInterview = await response.json();
        setInterviews([newInterview, ...interviews]);
        // Reset form
        setRole("");
        setInterviewType("");
        setExperienceLevel("");
        setNumQuestions(5);
      } else {
        alert('Error generating interview');
      }
    } catch (error) {
      console.error('Error generating interview:', error);
      alert('Error generating interview');
    } finally {
      setGenerating(false);
    }
  };

  const handleInterviewGenerated = (interviewData: Interview) => {
    setInterviews([interviewData, ...interviews]);
    setChatbotOpen(false);
  };

  if (!user) {
    return null;
  }

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 text-foreground font-sans relative overflow-hidden">
      {/* Enhanced Animated Background */}
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-purple-900/30 via-slate-900/50 to-slate-900 pointer-events-none"></div>
      <div className="fixed inset-0 bg-grid-white/[0.03] bg-[size:60px_60px] pointer-events-none"></div>
      <div className="fixed inset-0 bg-gradient-to-r from-purple-500/5 via-transparent to-pink-500/5 pointer-events-none"></div>
      <div className="fixed inset-0 bg-gradient-to-b from-transparent via-purple-900/10 to-transparent pointer-events-none"></div>

      {/* Floating Elements */}
      <div className="fixed top-20 left-20 w-72 h-72 bg-purple-500/10 rounded-full blur-3xl animate-pulse pointer-events-none"></div>
      <div className="fixed bottom-20 right-20 w-96 h-96 bg-pink-500/10 rounded-full blur-3xl animate-pulse pointer-events-none delay-1000"></div>
      <div className="fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-gradient-to-r from-purple-500/5 to-cyan-500/5 rounded-full blur-3xl animate-pulse pointer-events-none delay-2000"></div>

      {/* Subtle Pattern Overlay */}
      <div className="fixed inset-0 opacity-5 pointer-events-none" style={{
        backgroundImage: `url("data:image/svg+xml,%3Csvg width='40' height='40' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.1'%3E%3Cpath d='M20 20c0 5.5-4.5 10-10 10s-10-4.5-10-10 4.5-10 10-10 10 4.5 10 10zm10 0c0 5.5-4.5 10-10 10s-10-4.5-10-10 4.5-10 10-10 10 4.5 10 10z'/%3E%3C/g%3E%3C/svg%3E")`,
        backgroundSize: '40px 40px'
      }}></div>

      {/* Mobile Sidebar Overlay */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-30 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Custom Layout Grid */}
      <div className="h-full grid grid-cols-1 gap-0 md:grid-cols-[16rem_1fr]">
        {/* Sidebar */}
        <div className={`h-full bg-gradient-to-br from-slate-900/80 via-purple-900/60 to-slate-900/80 border-r border-purple-500/30 backdrop-blur-xl shadow-2xl shadow-purple-500/20 z-40 transition-transform duration-300 md:translate-x-0 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:relative md:translate-x-0`}>
          {/* Mobile Close Button */}
          <button
            onClick={() => setSidebarOpen(false)}
            className="md:hidden absolute top-4 right-4 text-purple-300 hover:text-white transition-colors duration-200 z-50"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
          <SidebarHeader className="border-b border-purple-500/30 p-6">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 bg-gradient-to-r from-purple-400 to-pink-400 rounded-xl flex items-center justify-center">
                <span className="text-white font-bold text-lg">AI</span>
              </div>
              <div>
                <h3 className="text-white font-bold text-lg">AINEX</h3>
                <p className="text-purple-300 text-xs">Interview Platform</p>
              </div>
            </div>
            <SidebarMenu className="space-y-2">
              <SidebarMenuItem>
                <SidebarMenuButton className="text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white transition-all duration-300 rounded-lg p-3 backdrop-blur-md">
                  <Home className="text-purple-400" />
                  <span>Dashboard</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
              <SidebarMenuItem>
                <SidebarMenuButton className="text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white transition-all duration-300 rounded-lg p-3 backdrop-blur-md">
                  <FileText className="text-purple-400" />
                  <span>Interviews</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
              <SidebarMenuItem>
                <SidebarMenuButton className="text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white transition-all duration-300 rounded-lg p-3 backdrop-blur-md">
                  <UserCircle className="text-purple-400" />
                  <span>Profile</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            </SidebarMenu>
          </SidebarHeader>
          <SidebarContent className="p-4">
            <SidebarGroup>
              <SidebarGroupLabel className="text-purple-200/80 font-semibold mb-4 text-sm uppercase tracking-wider">Navigation</SidebarGroupLabel>
              <SidebarGroupContent>
                <SidebarMenu className="space-y-2">
                  <SidebarMenuItem>
                    <SidebarMenuButton className="text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white transition-all duration-300 rounded-lg p-3 backdrop-blur-md">
                      <Calendar className="text-purple-400" />
                      <span>Recent Interviews</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                  <SidebarMenuItem>
                    <SidebarMenuButton className="text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white transition-all duration-300 rounded-lg p-3 backdrop-blur-md">
                      <Users className="text-purple-400" />
                      <span>Community</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          </SidebarContent>
          <SidebarFooter className="border-t border-purple-500/30 p-4">
            <SidebarMenu>
              <SidebarMenuItem>
                <SidebarMenuButton className="text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white transition-all duration-300 rounded-lg p-3 backdrop-blur-md">
                  <Settings className="text-purple-400" />
                  <span>Settings</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            </SidebarMenu>
          </SidebarFooter>
        </div>

        {/* Main Content Area */}
        <div className="h-full flex flex-col">
          <Topbar isScrolled={isScrolled} onMenuToggle={() => setSidebarOpen(!sidebarOpen)} />
          <div className="pt-24 h-full overflow-auto">
            <DashboardContainer
              interviews={interviews}
              loading={loading}
              generating={generating}
              chatbotOpen={chatbotOpen}
              setChatbotOpen={setChatbotOpen}
              role={role}
              setRole={setRole}
              interviewType={interviewType}
              setInterviewType={setInterviewType}
              experienceLevel={experienceLevel}
              setExperienceLevel={setExperienceLevel}
              numQuestions={numQuestions}
              setNumQuestions={setNumQuestions}
              generateInterview={generateInterview}
              handleInterviewGenerated={handleInterviewGenerated}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
