"use client";

import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { User, LogOut, Sparkles, Menu } from "lucide-react";
import { useUser } from "@stackframe/stack";
import { SidebarTrigger } from "@/components/ui/sidebar";

interface TopbarProps {
  isScrolled: boolean;
  onMenuToggle?: () => void;
}

export default function Topbar({ isScrolled, onMenuToggle }: TopbarProps) {
  const user = useUser();
  const router = useRouter();

  const handleSignOut = async () => {
    await user?.signOut();
    router.push("/");
  };

  return (
    <nav
      className={`fixed w-full z-50 transition-all duration-500 ease-in-out ${
        isScrolled
          ? "bg-gradient-to-r from-slate-900/95 via-purple-900/95 to-slate-900/95 backdrop-blur-xl py-4 shadow-2xl border-b border-purple-500/40 shadow-purple-500/20"
          : "py-8 bg-gradient-to-r from-transparent via-purple-900/20 to-transparent backdrop-blur-sm"
      }`}
    >
      <div className="container mx-auto px-6 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <SidebarTrigger className="hidden md:flex text-purple-400 hover:text-white hover:bg-purple-500/30 transition-all duration-300 rounded-lg p-2 hover:shadow-lg hover:shadow-purple-500/30" />
          <button
            onClick={onMenuToggle}
            className="md:hidden text-purple-400 hover:text-white hover:bg-purple-500/30 transition-all duration-300 rounded-lg p-2 hover:shadow-lg hover:shadow-purple-500/30"
          >
            <Menu className="w-6 h-6" />
          </button>
          <div className="flex items-center gap-3">
            <div className="relative">
              <h1 className="text-4xl font-black text-white tracking-tight">
                AI<span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 via-pink-400 to-cyan-400 animate-pulse">NEX</span>
              </h1>
              <div className="absolute -inset-1 bg-gradient-to-r from-purple-400 to-pink-400 rounded-lg blur opacity-20 animate-pulse"></div>
            </div>
            <span className="text-sm inline-flex items-center bg-gradient-to-r from-purple-500/30 to-pink-500/30 backdrop-blur-md border border-purple-500/40 rounded-full px-4 py-2 text-purple-200 font-medium shadow-lg">
              <Sparkles className="w-4 h-4 mr-2 text-yellow-400" />
              Dashboard
            </span>
          </div>
        </div>

        <div className="hidden lg:flex items-center space-x-4">
          <div className="flex items-center gap-3 text-gray-300 bg-gradient-to-r from-slate-800/60 to-purple-800/60 px-4 py-3 rounded-full border border-purple-500/30 backdrop-blur-md shadow-lg hover:shadow-purple-500/20 transition-all duration-300">
            <div className="w-8 h-8 bg-gradient-to-r from-purple-400 to-pink-400 rounded-full flex items-center justify-center">
              <User size={16} className="text-white" />
            </div>
            <span className="text-sm font-medium">Welcome, {user?.primaryEmail || "User"}</span>
          </div>
          <Button
            variant="outline"
            className="border-purple-500/60 text-purple-300 hover:bg-gradient-to-r hover:from-purple-500/30 hover:to-pink-500/30 hover:text-white hover:border-purple-400 transition-all duration-300 rounded-lg px-4 py-2 backdrop-blur-md shadow-lg hover:shadow-purple-500/30"
            onClick={() => router.push("/dashboard")}
          >
            Dashboard
          </Button>
          <Button
            variant="outline"
            className="border-gray-500/60 text-gray-300 hover:bg-gradient-to-r hover:from-gray-500/30 hover:to-purple-500/30 hover:text-white hover:border-gray-400 transition-all duration-300 rounded-lg px-4 py-2 backdrop-blur-md shadow-lg hover:shadow-gray-500/30"
            onClick={handleSignOut}
          >
            <LogOut size={16} className="mr-2" />
            Sign Out
          </Button>
        </div>
      </div>
    </nav>
  );
}